import type { SitePickerOption, ListPickerOption, FieldPickerOption, ViewPickerOption, ContentTypePickerOption, ListItemPickerOption, PrincipalPickerOption, PickerOption } from '../../../packages/spfx-react-toolkit/src/controls/pickers/picker.types';
export const web = 'https://tenant.test/sites/hr', tenant = '11111111-1111-4111-8111-111111111111';
export const guid = (i: number): string => `${String(i).padStart(8, '0')}-1111-4111-8111-111111111111`;
export const names = ['SitePicker', 'ListPicker', 'FieldPicker', 'ViewPicker', 'ContentTypePicker', 'ListItemPicker', 'PrincipalPicker'] as const;
export type Name = typeof names[number];
export const sites: readonly SitePickerOption[] = Array.from({ length: 7 }, (_, i) => ({ key: `site-${i}`, text: `Site ${i}`, url: i === 0 ? web : `https://tenant.test/sites/collection${i}`, value: { kind: 'site', url: i === 0 ? web : `https://tenant.test/sites/collection${i}` } }));
export const lists: readonly ListPickerOption[] = Array.from({ length: 35 }, (_, i) => ({ key: `list-${i}`, text: `List ${i}`, webUrl: web, id: guid(i + 1), title: `List ${i}`, baseTemplate: i === 0 ? 101 : 100, hidden: false, value: { kind: 'list', webUrl: web, listId: guid(i + 1) } }));
export const fields: readonly FieldPickerOption[] = Array.from({ length: 35 }, (_, i) => ['Text', 'Choice', 'Number', 'DateTime', 'User', 'Lookup', 'Boolean'][i % 7]).map((typeAsString, i) => ({ key: `field-${i}`, text: `Field ${i}`, webUrl: web, listId: guid(1), id: guid(i + 10), title: `Field ${i}`, internalName: `Field${i}`, typeAsString, fieldTypeKind: i + 2, hidden: false, readOnly: false, group: 'Demo', value: { kind: 'field', webUrl: web, listId: guid(1), fieldId: guid(i + 10), internalName: `Field${i}` } }));
export const views: readonly ViewPickerOption[] = Array.from({ length: 35 }, (_, i) => ({ key: `view-${i}`, text: `View ${i}`, webUrl: web, listId: guid(1), id: guid(i + 20), title: `View ${i}`, defaultView: i === 0, personalView: i === 1, value: { kind: 'view', webUrl: web, listId: guid(1), viewId: guid(i + 20) } }));
export const contentTypes: readonly ContentTypePickerOption[] = Array.from({ length: 35 }, (_, i) => ({ key: `ct-${i}`, text: `Content type ${i}`, kind: 'contentType', webUrl: web, id: `0x0101${(i + 1).toString(16).padStart(2, '0')}`, name: `Content type ${i}`, group: i % 2 ? 'Custom' : 'Demo', description: `Content type ${i} description`, hidden: i === 1, readOnly: i === 2, sealed: i === 3, value: { kind: 'contentType', scope: 'site', webUrl: web, contentTypeId: `0x0101${(i + 1).toString(16).padStart(2, '0')}` } }));
export const listContentTypes: readonly ContentTypePickerOption[] = contentTypes.map(option => ({ ...option, key: `list-${option.key}`, value: { ...option.value, scope: 'list', listId: guid(1) } }));
export const items: readonly ListItemPickerOption[] = Array.from({ length: 7 }, (_, i) => ({ key: `item-${i}`, text: i === 0 ? 'Contract.pdf' : `Item ${i}`, webUrl: web, listId: guid(1), itemId: i + 1, kind: i === 0 ? 'file' : 'item', fileExtension: i === 0 ? 'pdf' : undefined, keyValue: i + 1, fields: { Title: `Item ${i}` }, value: i === 0 ? { kind: 'file', webUrl: web, listId: guid(1), itemId: i + 1, uniqueId: guid(40), extension: 'pdf' } : { kind: 'item', webUrl: web, listId: guid(1), itemId: i + 1 } }));
export const principals: readonly PrincipalPickerOption[] = Array.from({ length: 7 }, (_, i) => ({ kind: 'user', key: `user-${i}`, text: `User ${i}`, loginName: `user${i}@tenant.test`, userPrincipalName: `user${i}@tenant.test`, email: `user${i}@tenant.test`, entraId: guid(i + 50), entraTenantId: tenant, value: { kind: 'user', loginName: `user${i}@tenant.test`, entra: { tenantId: tenant, id: guid(i + 50) } } }));
export const datasets: Readonly<Record<Name, readonly PickerOption[]>> = { SitePicker: sites, ListPicker: lists, FieldPicker: fields, ViewPicker: views, ContentTypePicker: contentTypes, ListItemPicker: items, PrincipalPicker: principals };
